import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { getSettingInt, getSettingBool } from "../lib/settings";
import { notifyAdmins } from "./monitor";

/**
 * Outbound-abuse detection. Compares each running server's cumulative outbound
 * byte counter (Server.bwOutBytes, updated by the metering sweep) against the
 * previous sample to compute a sustained outbound rate. A rate over the
 * configurable threshold (a compromised VM sending spam / DDoS egress / port
 * scanning) raises an AbuseAlert, notifies admins, and — if auto-suspend is on —
 * suspends the worst offenders. Protects the platform's (and mail) IP reputation.
 *
 * Settings: `abuse_outbound_mbps` (default 200), `abuse_autosuspend` (default false).
 */
export async function abuseSweep(): Promise<void> {
  if (SANDBOX) return; // no real traffic to measure in the sandbox

  const thresholdMbps = await getSettingInt("abuse_outbound_mbps", 200);
  const autoSuspend = await getSettingBool("abuse_autosuspend", false);
  const now = new Date();

  const servers = await db.server.findMany({
    where: { status: "RUNNING" },
    select: { id: true, userId: true, hostname: true, bwOutBytes: true, abuseBwMark: true, abuseBwMarkAt: true },
  });

  for (const s of servers) {
    const mark = s.abuseBwMark;
    const markAt = s.abuseBwMarkAt;
    // Re-mark for the next window regardless of outcome.
    await db.server.update({ where: { id: s.id }, data: { abuseBwMark: s.bwOutBytes, abuseBwMarkAt: now } });

    if (mark == null || markAt == null) continue;
    const deltaBytes = Number(s.bwOutBytes - mark);
    const windowSec = (now.getTime() - markAt.getTime()) / 1000;
    // Skip counter resets (reboot/reprovision → negative delta) and too-short windows.
    if (deltaBytes <= 0 || windowSec < 30) continue;

    const mbps = (deltaBytes * 8) / windowSec / 1_000_000;
    if (mbps < thresholdMbps) continue;

    // One open alert per server+kind; don't spam admins every sweep.
    const existing = await db.abuseAlert.findFirst({
      where: { serverId: s.id, kind: "BANDWIDTH_SPIKE", status: "OPEN" },
    });
    if (existing) continue;

    const severity = mbps >= thresholdMbps * 3 ? "HIGH" : "MEDIUM";
    await db.abuseAlert.create({
      data: {
        serverId: s.id,
        userId: s.userId,
        kind: "BANDWIDTH_SPIKE",
        severity,
        detail: `Sustained ~${mbps.toFixed(0)} Mbps outbound on ${s.hostname} (threshold ${thresholdMbps} Mbps).`,
        metric: { mbps: Math.round(mbps), windowSec: Math.round(windowSec), bytes: deltaBytes },
      },
    });
    await notifyAdmins(
      `Abuse alert: outbound spike on ${s.hostname}`,
      `${s.hostname} is pushing ~${mbps.toFixed(0)} Mbps outbound over ${Math.round(windowSec)}s ` +
        `(threshold ${thresholdMbps} Mbps). Possible spam, DDoS egress, or port scanning. Review in the admin abuse queue.`,
    );

    // Auto-suspend only the worst (HIGH) offenders, and only if the operator opted in.
    if (autoSuspend && severity === "HIGH") {
      await db.job.create({ data: { type: "SUSPEND", serverId: s.id } });
      await db.abuseAlert.updateMany({
        where: { serverId: s.id, kind: "BANDWIDTH_SPIKE", status: "OPEN" },
        data: { status: "ACTIONED" },
      });
      await notifyAdmins(
        `Auto-suspended ${s.hostname} for outbound abuse`,
        `${s.hostname} exceeded 3× the outbound threshold and was auto-suspended (abuse_autosuspend is on).`,
      );
    }
  }
}

