/** Sections that are billing-adjacent are gated on the "billing" area; the rest
 *  on "platform". BILLING-role staff may thus edit money-facing knobs. */
const BILLING_SECTIONS = new Set(["billing", "domains", "dedicated-ip"]);

type Result = { ok?: boolean; error?: string };

/**
 * Persist one section of settings. Bind the section server-side in the panel
 * (`saveSettings.bind(null, "general")`) so it's never client-supplied; React's
 * useActionState then supplies (prevState, formData).
 */
export async function saveSettings(
  section: string,
  _prev: Result | undefined,
  formData: FormData,
): Promise<Result> {
  const fields = SECTION_FIELDS[section];
  if (!fields) return { error: "Unknown settings section." };

  const area = BILLING_SECTIONS.has(section) ? "billing" : "platform";
  const user = await requireArea(area);

  const changes: { key: string; value: string }[] = [];

  for (const f of fields) {
    const raw = formData.get(f.key);

    if (f.type === "bool") {
      changes.push({ key: f.key, value: raw ? "true" : "false" });
      continue;
    }

    if (f.type === "secret") {
      const v = (raw ?? "").toString();
      if (v.trim() === "") continue; // never clear/overwrite a stored secret with blank
      changes.push({ key: f.key, value: v });
      continue;
    }

    if (f.type === "int") {
      const s = (raw ?? "").toString().trim();
      if (s === "") {
        changes.push({ key: f.key, value: SETTINGS_DEFAULTS[f.key as keyof typeof SETTINGS_DEFAULTS] ?? "0" });
        continue;
      }
      const n = Number(s);
      if (!Number.isFinite(n)) return { error: `“${f.key}” must be a number.` };
      changes.push({ key: f.key, value: String(Math.round(n)) });
      continue;
    }

    changes.push({ key: f.key, value: (raw ?? "").toString().trim() });
  }

  if (changes.length === 0) return { ok: true };

  await db.$transaction(
    changes.map((c) =>
      db.setting.upsert({ where: { key: c.key }, update: { value: c.value }, create: { key: c.key, value: c.value } }),
    ),
  );

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "settings.save",
      detail: `${section}: ${changes.map((c) => c.key).join(", ")}`,
    },
  });

  revalidatePath("/admin/settings");
  return { ok: true };
}

const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
  : 14;
const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
  : 7;

async function dunningConfig(): Promise<DunningConfig> {
  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);

  // Clamp. These are free-text number fields in an admin panel and the action they
  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
  // same day it is suspended, or before the dunning sequence has even finished. The
  // floor includes the slip cap because a card sequence that started late can push
  // the suspension itself out to CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS, and
  // termination must always land AFTER the suspension it follows.
  const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
  terminateDays = Math.max(terminateDays, latestSuspendDay + 1);
  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
  return { graceDays, warnDays, terminateDays, autoSuspend };
}

