/**
 * Shared, READ-ONLY monitoring helpers for Nxeon.
 *
 * Everything here is safe to call from server components (status page, admin
 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
 * no secrets in the returned shapes — the public /status page renders off the
 * same `getHealth()` logic the API exposes.
 *
 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
 */

export type CompStatus = "operational" | "degraded" | "down";
export type Component = { status: CompStatus; detail: string };

export type HealthReport = {
  web: Component;
  db: Component;
  worker: Component;
  proxmox: Component;
  checkedAt: string;
