// Plain (non-"use server") module: constants + types for the Improvements board.
// A "use server" file may ONLY export async functions, so these live here and are
// imported by both the server actions and the client board component.

export const IMPROVEMENT_STATUSES = [
  "PROPOSED",
  "APPROVED",
  "DECLINED",
  "IN_PROGRESS",
  "DONE",
] as const;

export type ImprovementStatus = (typeof IMPROVEMENT_STATUSES)[number];

/** Selector for a bulk status change: an explicit id list and/or a filter. */
export type BulkImprovementSelector = {
  /** Explicit row ids. */
  ids?: string[];
  /** Restrict to a category (e.g. "bug"). */
  category?: string;
  /** Only touch rows currently in this status (e.g. only PROPOSED). */
  onlyStatus?: string;
};

export function isImprovementStatus(status: string): status is ImprovementStatus {
  return (IMPROVEMENT_STATUSES as readonly string[]).includes(status);
}
